// Generated by npm run build.
(() => {
const defaults = [
  { name: 'Wikipedia', keyword: 'w', template: 'https://en.wikipedia.org/w/index.php?search={search}' },
  { name: 'YouTube', keyword: 'yt', template: 'https://www.youtube.com/results?search_query={search}' }
];

const sourcePatterns = [
  'https://www.google.com/*', 'https://www.bing.com/*', 'https://duckduckgo.com/*'
];
const sources = [
  'www\\.google\\.com/search',
  'www\\.bing\\.com/search',
  'duckduckgo\\.com/'
];

function validate(entries) {
  if (!Array.isArray(entries) || entries.length > 100) throw new Error('Use an array of up to 100 shortcuts.');
  const seen = new Set();
  return entries.map(entry => {
    if (!entry || typeof entry.name !== 'string' || !entry.name.trim()) throw new Error('Each shortcut needs a name.');
    if (typeof entry.keyword !== 'string' || !/^[a-z][a-z0-9-]{0,19}$/.test(entry.keyword)) throw new Error('Keywords must use 1–20 lowercase letters, digits, or hyphens, starting with a letter.');
    if (seen.has(entry.keyword)) throw new Error(`Duplicate keyword: ${entry.keyword}`);
    seen.add(entry.keyword);
    if (entry.kind !== undefined && !['search', 'site'].includes(entry.kind)) throw new Error('Choose a search or website shortcut.');
    const site = entry.kind === 'site';
    if (typeof entry.template !== 'string' || (site ? /[{}]/.test(entry.template) : entry.template.split('{search}').length !== 2)) throw new Error(site ? 'Website URLs cannot contain placeholders.' : 'Each search URL needs exactly one {search} placeholder.');
    let url;
    try { url = new URL(entry.template); } catch { throw new Error('Enter a valid HTTPS search URL.'); }
    if (url.protocol !== 'https:' || url.username || url.password || url.hash || /[\\\r\n]/.test(entry.template)) throw new Error('Use an HTTPS URL without credentials, fragments, or backslashes.');
    const queryTemplate = [...url.searchParams.values()].includes('{search}') && /[?&][^=&?#]+=\{search\}(?:&|$)/.test(entry.template);
    const pathTemplate = !url.search && url.pathname.endsWith('%7Bsearch%7D') && entry.template.endsWith('/{search}');
    if (!site && !queryTemplate && !pathTemplate) throw new Error('Use {search} as a query value, or end a Go Link URL with /{search}.');
    if (site && /[\\{}]/.test(entry.template)) throw new Error('Enter a plain HTTPS website URL.');
    return { name: entry.name.trim().slice(0, 80), keyword: entry.keyword, template: entry.template, ...(site ? { kind: 'site' } : {}) };
  });
}

function requiredOrigins(entries) {
  return [...new Set([...sourcePatterns, ...validate(entries).map(e => `${new URL(e.template).origin}/*`)])];
}

function compile(entries) {
  let id = 1;
  // Safari's content-rule parser does not support alternation or noncapturing groups.
  // Separate separator/parameter-position variants keep the search in capture 1.
  return validate(entries).flatMap(entry => entry.kind === 'site' ? sources.flatMap(source =>
    ['', '[^#]*&'].map(prefix => ({
      id: id++, priority: 1,
      action: { type: 'redirect', redirect: { url: entry.template } },
      condition: { regexFilter: `^https://${source}\\?${prefix}q=${entry.keyword}(&[^#]*)?(#.*)?$`, isUrlFilterCaseSensitive: true, resourceTypes: ['main_frame'] }
    }))
  ) : sources.flatMap(source =>
    ['', '[^#]*&'].flatMap(prefix => ['\\+', '%20'].map(separator => ({
      id: id++, priority: 1,
      action: { type: 'redirect', redirect: { regexSubstitution: entry.template.replace('{search}', '\\1') } },
      condition: {
        regexFilter: `^https://${source}\\?${prefix}q=${entry.keyword}${separator}(${entry.template.endsWith('/{search}') ? '[A-Za-z0-9][A-Za-z0-9._~-]*' : '[^&#]+'})(&[^#]*)?(#.*)?$`,
        isUrlFilterCaseSensitive: true,
        resourceTypes: ['main_frame']
      }
    })))
  ));
}


async function install(entries) {
  const shortcuts = validate(entries);
  const rules = compile(shortcuts);
  for (const rule of rules) {
    const result = await browser.declarativeNetRequest.isRegexSupported({ regex: rule.condition.regexFilter, isCaseSensitive: true, requireCapturing: true });
    if (!result.isSupported) throw new Error(`Safari rejected a routing rule: ${result.reason || 'unsupported expression'}`);
  }
  const previous = await browser.declarativeNetRequest.getDynamicRules();
  await browser.declarativeNetRequest.updateDynamicRules({ removeRuleIds: previous.map(rule => rule.id), addRules: rules });
  await browser.storage.local.set({ shortcuts });
  return shortcuts;
}

let queue = Promise.resolve();
function enqueue(work) {
  const next = queue.then(work);
  queue = next.catch(() => {});
  return next;
}

browser.runtime.onInstalled.addListener(() => {
  enqueue(async () => {
    const { shortcuts } = await browser.storage.local.get('shortcuts');
    await install(shortcuts ?? defaults);
  }).catch(error => console.error('Go Search setup failed:', error.message));
});

browser.runtime.onMessage.addListener((message, sender) => {
  if (!sender.url?.startsWith(browser.runtime.getURL('')) || sender.tab) return;
  if (message.type === 'routing-status') return enqueue(async () => {
    try {
      const { shortcuts = defaults } = await browser.storage.local.get('shortcuts');
      const expected = compile(shortcuts);
      const rules = await browser.declarativeNetRequest.getDynamicRules();
      const permitted = await browser.permissions.contains({ origins: requiredOrigins(shortcuts) });
      const active = rules.length === expected.length && expected.every(rule => rules.some(actual => actual.id === rule.id && actual.condition.regexFilter === rule.condition.regexFilter && actual.action.redirect?.regexSubstitution === rule.action.redirect.regexSubstitution && actual.action.redirect?.url === rule.action.redirect.url));
      return { ready: active && permitted, permitted, count: shortcuts.length };
    } catch (error) { return { error: error.message }; }
  });
  if (message.type !== 'save-shortcuts') return;
  return enqueue(async () => {
    try {
      if (!await browser.permissions.contains({ origins: requiredOrigins(message.shortcuts) })) throw new Error('Allow the source and destination websites before saving.');
      return { shortcuts: await install(message.shortcuts) };
    } catch (error) { return { error: error.message }; }
  });
});

// Only origin-level counts leave the observer. No titles, paths, queries or page content.
const learningKey = 'learningV1';
const learningOrigins = ['https://*/*'];
const dayMS = 86400000;
const retentionDays = 30;
const maxSites = 100;
const ignoredHosts = new Set(['www.google.com', 'www.bing.com', 'duckduckgo.com']);

function emptyLearning(enabled = false) {
  return { enabled, sites: [], dismissed: [], generation: 0 };
}
function siteOrigin(raw) {
  try {
    const url = new URL(raw);
    if (url.protocol !== 'https:' || url.username || url.password || ignoredHosts.has(url.hostname)) return null;
    return url.origin;
  } catch { return null; }
}
function pruneLearning(state, now = Date.now()) {
  const cutoff = Math.floor(now / dayMS) - retentionDays + 1;
  const pruned = { ...emptyLearning(), ...state,
    sites: (state?.sites || []).filter(site => siteOrigin(site.origin) === site.origin).map(site => ({ ...site,
      days: (site.days || []).filter(day => day.day >= cutoff && day.day <= Math.floor(now / dayMS))
    })).filter(site => site.days.length).sort((a, b) => b.lastVisit - a.lastVisit).slice(0, maxSites),
    dismissed: (state?.dismissed || []).filter(origin => siteOrigin(origin) === origin).slice(-maxSites)
  };
  // A cache can contain host-derived names and its signature contains origins.
  // Remove it when expired or when any referenced origin has aged out.
  if (pruned.cache) {
    let origins;
    try { origins = JSON.parse(pruned.cache.signature); } catch {}
    const retained = new Set(pruned.sites.map(site => site.origin));
    if (!(pruned.cache.until > now) || !Array.isArray(origins) || origins.some(origin => !retained.has(origin))) delete pruned.cache;
  }
  return pruned;
}
function recordVisit(state, tab, now = Date.now()) {
  if (!state?.enabled || tab?.incognito !== false || !tab.active || tab.status !== 'complete') return state;
  const origin = siteOrigin(tab.url);
  if (!origin || state.dismissed?.includes(origin)) return state;
  const next = structuredClone(pruneLearning(state, now));
  let site = next.sites.find(item => item.origin === origin);
  // Reloads, redirect chains and rapid tab switching count as one visit.
  if (site && now - site.lastVisit < 30 * 60000) return state;
  if (!site) { site = { origin, days: [], lastVisit: now }; next.sites.push(site); }
  const day = Math.floor(now / dayMS);
  const bucket = site.days.find(item => item.day === day);
  if (bucket) bucket.count = Math.min(20, bucket.count + 1);
  else site.days.push({ day, count: 1 });
  site.lastVisit = now;
  return pruneLearning(next, now);
}
function uniqueKeyword(preferred, used) {
  let base = String(preferred).toLowerCase().replace(/[^a-z0-9-]/g, '').replace(/^[^a-z]+/, '').slice(0, 16) || 'site';
  let key = base;
  for (let i = 2; used.has(key); i++) key = `${base}${i}`;
  used.add(key);
  return key;
}
function suggestSites(state, entries, now = Date.now()) {
  if (!state?.enabled) return [];
  const existing = new Set(entries.map(entry => new URL(entry.template).origin));
  const used = new Set(entries.map(entry => entry.keyword));
  return pruneLearning(state, now).sites.map(site => ({ ...site,
    visits: site.days.reduce((sum, day) => sum + day.count, 0),
    score: site.days.reduce((sum, day) => sum + day.count * Math.pow(0.93, Math.floor(now / dayMS) - day.day), 0)
  })).filter(site => site.visits >= 3 && site.days.length >= 2 && !existing.has(site.origin) && !state.dismissed.includes(site.origin))
    .sort((a, b) => b.score - a.score || a.origin.localeCompare(b.origin)).slice(0, 3).map(site => {
      const host = new URL(site.origin).hostname.replace(/^www\./, '');
      const parts = host.split('.');
      const label = ['dash', 'app', 'console', 'en'].includes(parts[0]) && parts.length > 2 ? parts[1] : parts[0];
      return { origin: site.origin, name: host, keyword: uniqueKeyword(label, used), kind: 'site', template: `${site.origin}/`, visits: site.visits, days: site.days.length, source: 'frequency' };
    });
}
function applyLabels(candidates, labels, entries) {
  const used = new Set(entries.map(entry => entry.keyword));
  return candidates.map((site, index) => {
    const label = Array.isArray(labels) ? labels.find(item => item.index === index) : null;
    const valid = label && typeof label.name === 'string' && label.name.trim() && /^[\p{L}\p{N} .&'-]{1,60}$/u.test(label.name)
      && typeof label.keyword === 'string' && /^[a-z][a-z0-9-]{0,19}$/.test(label.keyword);
    return { ...site, name: valid ? label.name.trim() : site.name, keyword: uniqueKeyword(valid ? label.keyword : site.keyword, used), source: valid ? 'on-device' : 'frequency' };
  });
}


// Separate serialization from shortcut installation. Inference never holds either queue.
let learningQueue = Promise.resolve();
function serializeLearning(work) {
  const result = learningQueue.then(work);
  learningQueue = result.catch(() => {});
  return result;
}
async function readLearning() {
  const stored = await browser.storage.local.get(learningKey);
  const previous = stored[learningKey] || emptyLearning();
  const current = pruneLearning(previous);
  // Retention applies to persisted browsing data, even without another visit.
  if (JSON.stringify(previous) !== JSON.stringify(current)) await writeLearning(current);
  return current;
}
async function writeLearning(state) { await browser.storage.local.set({ [learningKey]: state }); }
async function observeTab(tab) {
  return serializeLearning(async () => {
    const state = await readLearning();
    if (!state.enabled || tab?.incognito !== false || !tab.active || tab.status !== 'complete') return;
    const origin = siteOrigin(tab.url);
    if (!origin || !await browser.permissions.contains({ origins: [`${origin}/*`] })) return;
    const next = recordVisit(state, tab);
    if (next !== state) await writeLearning(next);
  });
}
browser.tabs.onUpdated.addListener((_id, change, tab) => {
  if (change.status === 'complete') observeTab(tab).catch(() => {});
});
browser.tabs.onActivated.addListener(({ tabId }) => {
  browser.tabs.get(tabId).then(observeTab).catch(() => {});
});
function nativeRequest(message, milliseconds = 8000) {
  let timer;
  return Promise.race([
    browser.runtime.sendNativeMessage('com.mengohlabs.gosearch', message),
    new Promise(resolve => { timer = setTimeout(() => resolve({ status: 'timeout', labels: [] }), milliseconds); })
  ]).catch(() => ({ status: 'unavailable', labels: [] })).finally(() => clearTimeout(timer));
}
let enrichment;
async function suggestions(enhance) {
  const state = await serializeLearning(readLearning);
  const { shortcuts = defaults } = await browser.storage.local.get('shortcuts');
  const candidates = suggestSites(state, shortcuts);
  if (!state.enabled) return { enabled: false, suggestions: [], model: 'off' };
  if (!enhance) return { enabled: true, suggestions: candidates, model: 'frequency', observedSites: state.sites.length };
  const signature = JSON.stringify(candidates.map(site => site.origin));
  if (state.cache?.signature === signature && state.cache.until > Date.now()) {
    return { enabled: true, suggestions: applyLabels(candidates, state.cache.labels, shortcuts), model: state.cache.status };
  }
  const result = await nativeRequest(candidates.length ? {
    type: 'suggest-shortcuts', sites: candidates.map((site, index) => ({ index, host: new URL(site.origin).hostname, visits: site.visits, days: site.days }))
  } : { type: 'model-status' });
  // Forget/disable while inference is running must not resurrect any data.
  return serializeLearning(async () => {
    const current = await readLearning();
    if (!current.enabled || current.generation !== state.generation) return { enabled: current.enabled, suggestions: [], model: 'off' };
    const { shortcuts: latest = defaults } = await browser.storage.local.get('shortcuts');
    const fresh = suggestSites(current, latest);
    if (JSON.stringify(fresh.map(site => site.origin)) !== signature) return { enabled: true, suggestions: fresh, model: 'frequency' };
    const labels = Array.isArray(result?.labels) ? result.labels : [];
    const model = typeof result?.status === 'string' ? result.status : 'unavailable';
    current.cache = { signature, labels, status: model, until: Date.now() + (model === 'available' ? dayMSForCache : 15 * 60000) };
    await writeLearning(current);
    return { enabled: true, suggestions: applyLabels(fresh, labels, latest), model };
  });
}
const dayMSForCache = 86400000;

browser.runtime.onMessage.addListener((message, sender) => {
  if (!sender.url?.startsWith(browser.runtime.getURL('')) || sender.tab) return;
  if (message.type === 'learning-access') return browser.permissions.contains({ origins: learningOrigins }).then(allSites => ({ allSites }));
  if (message.type === 'suggestions') {
    if (!message.enhance) return suggestions(false);
    if (!enrichment) enrichment = suggestions(true).finally(() => { enrichment = null; });
    return enrichment;
  }
  if (message.type === 'learning-settings') return serializeLearning(async () => {
    const previous = await readLearning();
    // Safari can acknowledge an optional host request before the user grants
    // website access. Learning is opt-in, but each observed origin is checked above.
    const next = message.enabled ? { ...previous, enabled: true } : emptyLearning(false);
    next.generation = previous.generation + 1;
    delete next.cache;
    await writeLearning(next);
    return { enabled: next.enabled };
  });
  if (message.type === 'dismiss-suggestion') return serializeLearning(async () => {
    const state = await readLearning();
    if (typeof message.origin !== 'string' || !state.sites.some(site => site.origin === message.origin)) return { error: 'Suggestion no longer exists.' };
    state.dismissed = [...new Set([...state.dismissed, message.origin])].slice(-100);
    state.sites = state.sites.filter(site => site.origin !== message.origin);
    delete state.cache;
    state.generation++;
    await writeLearning(state);
    return { ok: true };
  });
});

})();
